"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),cp=require('node:child_process');
const C=require('./match-contract-separation-v0.1-capture.cjs'),s=C.json(C.prefix+'source-evidence.json'),f=C.json(C.prefix+'findings-evidence.json');
const integrity=C.integrity();assert.equal(integrity.preservedExistingHashes,1477);
for(const item of [...s.newExactSnippets,...s.priorExactSnippetsReverified.snippets]){assert.equal(C.fileHash(item.path),item.sha256);const lines=fs.readFileSync(path.join(C.root,item.path),'utf8').split(/\r?\n/);assert.equal(lines.slice(item.startLine-1,item.endLine).join('\n')+'\n',item.source);}
for(const item of s.diagnosticSources)assert.equal(C.fileHash(item.path),item.sha256);
assert.equal(f.protectionMatrix.length,12);assert(f.protectionMatrix.every(r=>r.formallyReplaced===false));assert.equal(f.summary.original36Boolean,false);assert.equal(f.synthetic.Moment3.status,'UNVERIFIED');assert.equal(f.synthetic.Moment3.finalGateTrueTicks,0);
const rawPath=C.childPrefix+'proof-evidence.json',raw=C.json(rawPath);assert.equal(raw.status,'PASS');assert.equal(raw.exitCode,0);assert(raw.entryVerified&&raw.sourceStable);assert.equal(raw.stderr,'');
for(const [p,h] of Object.entries(raw.relevantSourceHashesAfter))assert.equal(C.fileHash(p),h,p);
const prefix='MATCH_CONTRACT_SEPARATION_PROOF=',proof=JSON.parse(raw.stdout.split(/\r?\n/).find(l=>l.startsWith(prefix)).slice(prefix.length)),m=proof.facts.finalMatch;
assert.equal(m.pendingOffensiveOpportunity.status,'resolved');assert.equal(m.pendingOffensiveOpportunity.resultApplied,true);assert.equal(m.offensivePlateAppearanceState.resultApplied,true);assert.equal(m.activeSituation??null,null);assert.equal(m.pendingDefensiveResumeState,null);assert.equal(m.currentMomentId,'');assert.equal(m.simulationPhase,'complete');
assert.deepEqual(proof.facts.finalPlayer.highSchoolYearOneMatchHistory[0].gameRecordSummary.finalScore,m.gameRecord.result.finalScore);
assert.equal(m.gameExposureState.opportunitySnapshot.debug.opportunityScore,44);assert.equal(proof.facts.seedBoundary.sameOpportunityDerivedSeed,105959684);
const driver=fs.readFileSync(path.join(C.root,C.prefix+'proof.cjs'),'utf8');assert(!/completedMoments\s*=(?!=)|completedMoments\.(push|splice|unshift)\s*\(/.test(driver),'Diagnostic must not write completed Moments');
const report=fs.readFileSync(path.join(C.root,C.report),'utf8'),links=[...report.matchAll(/\]\(([^)]+)\)/g)].map(m=>m[1]);
const pending=[C.prefix+'verification-evidence.json',C.prefix+'closeout-evidence.json',C.prefix+'delivery-evidence.json'];
for(const href of links){const p=path.resolve(C.root,'docs',href.split('#')[0]);assert(fs.existsSync(p)||pending.some(f=>path.resolve(C.root,f)===p),'Missing link '+href);}
for(const text of ['Ready for Phase B2','Ready for Commit','Ready for Sprint10B','UNVERIFIED','C88222','S38','105959684'])assert(report.includes(text),text);
const scripts=C.files().filter(p=>C.isNew(p)&&p.endsWith('.cjs'));
const syntax=scripts.map(file=>{const args=['--check',path.join(C.root,file)],r=cp.spawnSync(process.execPath,args,{cwd:C.root,encoding:'utf8',windowsHide:true,timeout:10000,maxBuffer:1000000});assert.equal(r.status,0,r.stderr);return{file,actualCommand:[process.execPath,...args],entry:'Node syntax-only',stdout:r.stdout,stderr:r.stderr,exitCode:r.status,signal:r.signal,error:r.error?.message||null,timeoutMs:10000};});
const directSources=[C.prefix+'verify.cjs',C.prefix+'finalize.cjs'].map(p=>({path:p,sha256:C.fileHash(p),source:fs.readFileSync(path.join(C.root,p),'utf8')}));
C.capture('verification',{...integrity,report:{path:C.report,sha256:C.fileHash(C.report),linksChecked:links.length,onlyPendingLinks:pending},newExactSnippetCount:s.newExactSnippetCount,priorExactSnippetsReverified:s.priorExactSnippetsReverified.count,allSourceStillCurrent:true,syntax,directSources,acceptedChild:{path:rawPath,sha256:C.fileHash(rawPath),actualCommand:raw.actualCommand,entry:raw.entryMode,status:raw.status,exitCode:raw.exitCode,elapsedMs:raw.elapsedMs,limits:raw.policy,entryVerified:raw.entryVerified,sourceStable:raw.sourceStable,successfulNodeAssertionCalls:raw.successfulAssertions,witnessPath:raw.witnessPath,witnessSha256:C.fileHash(raw.witnessPath),stdoutSha256:C.hash(raw.stdout),stderr:raw.stderr},additionalReadOnlyAssertions:{pendingOffensiveOpportunityResolved:true,offensiveResultApplied:true,noActiveOrPendingDefensiveSituation:true,currentMomentIdEmpty:true,historyRecordScoreMatches:true,opportunityScore44:true,derivedSeed105959684:true,noDiagnosticCompletedMomentWrites:true},acceptedContractScope:{S1:'CONFIRMED bounded',S3:'UNVERIFIED',canonical88221:'Structural and identity checks confirmed for substitute; C9 temporal semantics not accepted',canonical88222:'UNVERIFIED / NOT RUN',original38:'UNVERIFIED / NOT RUN',original36:'false in the observed game; original suite not invoked',anyOriginalAssertionFormallyReplaced:false},newDiagnosticChildren:1,newFullMatchExecutions:1,formalSuiteInvocations:0,suppliedOpportunityFullMatches:0,seed88222Matches:0,full251:0,r6Full227:0,firstBaseTiming:0,receiverV2Integration:0,browserSuites:0,productionDelta:0,formalTestDelta:0,existingFixtureSeedPinDelta:0,phaseB2Started:false,readyForPhaseB2:'NO',readyForCommit:'NO',readyForSprint10B:'NO'});
console.log(JSON.stringify({verification:'PASS',existingHashes:1477,newSnippets:s.newExactSnippetCount,priorSnippetsReverified:s.priorExactSnippetsReverified.count,syntaxFiles:syntax.length,links:links.length,protectionRows:12,formallyReplaced:false,S3:'UNVERIFIED',original36:false,readyForPhaseB2:'NO'}));

"use strict";
