const files=C.files().filter(C.isNew),hashes=Object.fromEntries(files.map(p=>[p,C.fileHash(p)]));
C.capture('delivery',{files,hashes,deliverySelfHashExcluded:true,unchangedExistingHashes:1477,changedExistingPaths:[],productionDelta:0,formalTestDelta:0,existingFixtureSeedPinDelta:0,allOldCapturesPreserved:true,protectedMetadataUnchanged:true,readyForPhaseB2:'NO',readyForCommit:'NO',readyForSprint10B:'NO',stopped:true});
const links=[...fs.readFileSync(path.join(C.root,C.report),'utf8').matchAll(/\]\(([^)]+)\)/g)].map(m=>m[1]);for(const href of links)assert(fs.existsSync(path.resolve(C.root,'docs',href.split('#')[0])),href);
for(const [p,h] of Object.entries(hashes))assert.equal(C.fileHash(p),h,p);C.integrity();
console.log(JSON.stringify({report:C.report,existingHashesPreserved:1477,newArtifacts:files.length+1,linksResolved:links.length,indexEmpty:integrity.git.index==='',productionDelta:0,formalTestDelta:0,originalAssertionsReplaced:false,readyForPhaseB2:'NO',stopped:true}));
